typedef enum { EV_CLICK, EV_KEY } ev_kind;
typedef struct {
    ev_kind kind;
    union { struct { int x, y; } click; char key; };  /* C11 anonymous union */
} event;

switch (ev.kind) {
case EV_CLICK: move(ev.click.x, ev.click.y); break;
case EV_KEY:   type(ev.key);                 break;
}   /* -Werror=switch turns a missing case into a build failure */
